import json,math,re,os,html
from pathlib import Path
_HERE = Path(__file__).resolve().parent
import sympy as S
from scipy.optimize import brentq, minimize_scalar
R=(_HERE.parents[1] / 'content/ib/math-aa-hl')
SRC=json.loads(Path(str(_HERE / 'reference-metadata' / 'IB Mathematics AA HL Questionbank - Geometry & Trigonometry.json')).read_text())
Q={}; x=S.symbols('x',real=True)
def L(v):return S.latex(S.simplify(v))
def N(v):
 t=format(float(v),'#.3g')
 if 'e' in t:
  m,e=t.split('e');return m+chr(92)+'times10^{'+str(int(e))+'}'
 return t
def G(v):return format(float(v),'.9g')
def V(v):return r'\begin{pmatrix}'+r'\\'.join(L(i) for i in v)+r'\end{pmatrix}'
def P(v):return '('+','.join(L(i) for i in v)+')'
def dot(a,b):return S.Matrix(a).dot(S.Matrix(b))
def cross(a,b):return S.Matrix(a).cross(S.Matrix(b))
def norm(v):return S.sqrt(dot(v,v))
def eqplane(n,p):return L(sum(n[i]*S.symbols('x y z')[i] for i in range(3)))+'='+L(dot(n,p))
def M(t):return ('M1',t)
def A(t,n=1):return ('A'+str(n),t)
def RR(t,n=1):return ('R'+str(n),t)
def add(n,title,stem,parts,solutions,diagram=None,msdiagram=None,note='Changed parameters; answers recomputed from the stated data. SymPy exact arithmetic and/or numerical evaluation used.'):
 src=SRC[n-1];groups=[];pp=[]
 for i,((prompt,marks),ss) in enumerate(zip(parts,solutions)):
  assert sum(0 if c=='AG' else int(c[1:]) for c,t in ss)==marks,(n,i,marks,ss)
  label=chr(97+i);pp.append({'label':label,'prompt':prompt,'marks':marks});groups.append({'part':label,'steps':[{'code':c,'text':t} for c,t in ss]})
 q={'id':f'ib-aa-gt-{n:03}','subject':'math-aa-hl','topicId':'geometry-trigonometry','collectionId':'geometry-trigonometry','number':n,'title':title,'subtopic':title,'difficulty':src['difficulty'],'calculator':src['calculator'],'marks':sum(p['marks'] for p in pp),'stem':stem,'parts':pp,'markScheme':groups,'source':{'document':'IB Mathematics AA HL Questionbank - Geometry & Trigonometry.pdf','question':n},'verification':{'method':'symbolic/numerical/reasoned','notes':note},'status':'published'}
 if diagram:q['diagramSvg']=diagram
 if msdiagram:q['markSchemeDiagramSvg']=msdiagram
 Q[n]=q

def save():
 p=R/'geometry-trigonometry.json';tmp=p.with_suffix('.tmp')
 with open(tmp,'w') as f:json.dump([Q[k] for k in sorted(Q)],f,ensure_ascii=False,indent=2);f.flush();os.fsync(f.fileno())
 os.replace(tmp,p)

def svg_graph(f,x0,x1,y0,y1,points=[],xticks=[],yticks=[]):
 w,h=560,310; X=lambda z:55+(float(z)-x0)/(x1-x0)*465;Y=lambda z:260-(float(z)-y0)/(y1-y0)*225
 bits=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 560 310" role="img" aria-label="Coordinate graph"><rect width="560" height="310" fill="white"/>']
 for z,label in xticks:
  px=X(z);bits.append(f'<line x1="{px}" y1="35" x2="{px}" y2="260" stroke="#e7e7e7"/><text x="{px}" y="282" text-anchor="middle" font-size="12">{html.escape(str(label))}</text>')
 for z,label in yticks:
  py=Y(z);bits.append(f'<line x1="55" y1="{py}" x2="520" y2="{py}" stroke="#e7e7e7"/><text x="45" y="{py+4}" text-anchor="end" font-size="12">{html.escape(str(label))}</text>')
 if x0<=0<=x1:bits.append(f'<line x1="{X(0)}" y1="30" x2="{X(0)}" y2="265" stroke="#333"/>')
 if y0<=0<=y1:bits.append(f'<line x1="50" y1="{Y(0)}" x2="525" y2="{Y(0)}" stroke="#333"/>')
 seg=[]
 for i in range(601):
  t=x0+(x1-x0)*i/600
  try:y=float(f(t))
  except: y=float('nan')
  if math.isfinite(y) and y0-.5<=y<=y1+.5:seg.append(f'{X(t):.2f},{Y(y):.2f}')
  else:
   if len(seg)>1:bits.append('<polyline points="'+' '.join(seg)+'" fill="none" stroke="#222" stroke-width="2"/>')
   seg=[]
 if len(seg)>1:bits.append('<polyline points="'+' '.join(seg)+'" fill="none" stroke="#222" stroke-width="2"/>')
 for a,b,lab in points:bits.append(f'<circle cx="{X(a)}" cy="{Y(b)}" r="3" fill="#222"/><text x="{X(a)+6}" y="{Y(b)-9}" font-size="12">{html.escape(lab)}</text>')
 bits.append('<text x="532" y="275" font-size="13">x</text><text x="34" y="24" font-size="13">y</text></svg>')
 return ''.join(bits)

def svg_sector(r,theta,segment=False,major=False):
 t=float(theta);cx,cy,rad=180,155,115;ax,ay=cx+rad,cy;bx,by=cx+rad*math.cos(t),cy-rad*math.sin(t)
 large=int(t>math.pi);path=f'M {ax} {ay} A {rad} {rad} 0 {large} 0 {bx} {by} '+('Z' if segment else f'L {cx} {cy} Z')
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 320" role="img" aria-label="Circle, labelled radii and shaded '+('segment' if segment else 'sector')+f'"><rect width="420" height="320" fill="white"/><circle cx="{cx}" cy="{cy}" r="{rad}" fill="none" stroke="#333"/><path d="{path}" fill="#e5e5e5" stroke="#333"/><line x1="{cx}" y1="{cy}" x2="{ax}" y2="{ay}" stroke="#333"/><line x1="{cx}" y1="{cy}" x2="{bx}" y2="{by}" stroke="#333"/><text x="164" y="174">O</text><text x="302" y="160">A</text><text x="{bx+4}" y="{by-7}">B</text><text x="228" y="176">{html.escape(str(r))}</text><text x="205" y="138">θ</text><text x="95" y="301" font-size="12">Diagram not necessarily to scale</text></svg>'

def trig_graph(n,kind,a,b,c,marks=(2,2,2),phase=0):
 a,b,c,phase=map(S.sympify,[a,b,c,phase]);expr=a*(S.sin(b*(x-phase)) if kind=='sin' else S.cos(b*(x-phase)))+c
 T=2*S.pi/b; f=S.lambdify(x,expr,'math');maxx=float(T); points=[]
 for t in [0,T/4,T/2,3*T/4,T]:
  y=expr.subs(x,t);points.append((float(t),float(y),f'({str(t).replace("pi","π")}, {y})'))
 svg=svg_graph(f,0,maxx,float(c-abs(a)-1),float(c+abs(a)+1),points,[(float(t),str(t).replace('pi','π')) for t in [0,T/4,T/2,3*T/4,T]],[(float(c-abs(a)),str(c-abs(a))),(float(c),str(c)),(float(c+abs(a)),str(c+abs(a)))])
 # Labelled points make the graph self-contained even in text-only printouts.
 stem=f'The graph shows one period of $f(x)=a\\{kind}(bx)+d$, where $b>0$. Its labelled points are '+', '.join('$'+P([t,expr.subs(x,t)])+'$' for t in [0,T/4,T/2,3*T/4,T])+'.'
 parts=[('Find $a$.',2),('Find the period and hence $b$.',3),('Find $d$.',2)]
 add(n,'Trigonometric graphs',stem,parts,[[M('Use half the maximum–minimum difference and the direction of the curve.'),A(f'$a={L(a)}$.')],[M('The period is the horizontal separation of consecutive maxima.'),A(f'$T={L(T)}$.'),A(f'$b=2\\pi/T={L(b)}$.')],[M('The midline is the mean of the maximum and minimum.'),A(f'$d={L(c)}$.')]],svg,note='Reference graph/parts partly omitted in PDF; complete new labelled graph retains amplitude, period and midline skills. Exact extrema verified from the new sinusoid.')

trig_graph(1,'cos',4,S.pi/3,2)
trig_graph(2,'cos',-3,S.pi/2,0)
trig_graph(4,'sin',-5,S.pi/4,0)

