def ratios(n,s,quadrant,items):
 s=S.Rational(s);c=(1 if quadrant==1 else -1)*S.sqrt(1-s*s);vals={'cos x':c,'sin 2x':2*s*c,'cos 2x':1-2*s*s,'tan 2x':S.simplify(2*s*c/(1-2*s*s))};formula={'cos x':r'\cos^2x=1-\sin^2x','sin 2x':r'\sin2x=2\sin x\cos x','cos 2x':r'\cos2x=1-2\sin^2x','tan 2x':r'\tan2x=\sin2x/\cos2x'}
 parts=[];sols=[]
 for key,m in items:
  parts.append((f'Find the exact value of $\\{key}$.',m));steps=[M('$'+formula[key]+'$.')]
  if m>=3:steps.append(A(f'$\\cos^2x={L(1-s*s)}$; hence $|\\cos x|={L(abs(c))}$.' if key=='cos x' else f'Use $\\sin x={L(s)}$ and $\\cos x={L(c)}$, with the sign fixed by the quadrant.'))
  if m>=4:steps.append(M('Simplify the exact fraction and rationalise where needed.'))
  steps.append(A(f'$\\{key}={L(vals[key])}$.',m-len(steps)))
  sols.append(steps)
 add(n,'Trigonometric identities',f'It is given that $\\sin x={L(s)}$ and '+('$0<x<\\pi/2$.' if quadrant==1 else '$\\pi/2<x<\\pi$.'),parts,sols)
