# Bearings: complete two-stage journeys.
def bearing_problem(n,l1,b1,l2,b2,extended=False):
 u=S.Matrix([l1*math.sin(math.radians(b1)),l1*math.cos(math.radians(b1))]);v=S.Matrix([l2*math.sin(math.radians(b2)),l2*math.cos(math.radians(b2))]);w=u+v;dist=float(norm(w));bearing=math.degrees(math.atan2(float(w[0]),float(w[1])))%360;internal=math.degrees(math.acos(float(dot(-u,v)/(l1*l2))));area=abs(float(u[0]*v[1]-u[1]*v[0]))/2
 parts=[('Find $\\angle ABC$.',2),('Find the direct distance $AC$.',3),('Find the bearing of $C$ from $A$.',3)]
 sols=[[M(f'The reverse bearing $BA$ is ${(b1+180)%360}^\\circ$.'),A(f'$\\angle ABC={N(internal)}^\\circ$.')],[M('Use the cosine rule, or resolve east and north components.'),A(f'$\\overrightarrow{{AC}}=({G(w[0])},{G(w[1])})$ in east–north coordinates.'),A(f'$AC={N(dist)}$ km.')],[M('Use the east and north components, with the correct quadrant.'),A(f'$\\operatorname{{atan2}}({G(w[0])},{G(w[1])})$.'),A(f'Bearing ${bearing:.1f}^\\circ$.')]]
 if extended:parts.append(('Find the area of triangle $ABC$.',3));sols.append([M('$K=\\frac12 AB\\cdot BC\\sin B$.'),A(f'$K=\\frac12({l1})({l2})\\sin({N(internal)}^\\circ)$.'),A(f'$K={N(area)}$ km$^2$.')])
 add(n,'Bearings and triangle geometry',f'A cyclist travels ${l1}$ km from $A$ to $B$ on a bearing of ${b1}^\\circ$, then ${l2}$ km from $B$ to $C$ on a bearing of ${b2}^\\circ$. Bearings are measured clockwise from north.',parts,sols)
bearing_problem(9,5,320,7,215)
bearing_problem(89,65,125,45,70,True)
# Negative sine model, extrema and finite-domain solutions.
aamp,mid,T=4,3,16;freq=2*math.pi/T;level=5;alpha=math.asin((level-mid)/(-aamp));roots=sorted({round((base+2*math.pi*k)/freq,12) for base in [alpha,math.pi-alpha] for k in range(-2,4) if 0<=((base+2*math.pi*k)/freq)<=20})
add(10,'Trigonometric graphs','A function $f(x)=p\\sin(qx)+r$, where $q>0$, has a minimum at $(4,-1)$ and the next maximum at $(12,7)$.',[('Find the period and $q$.',3),('Find $p$ and $r$.',3),('Solve $f(x)=5$ for $0\\le x\\le20$.',2)],[[M('The extrema are half a period apart.'),A('$T=16$.'),A('$q=\\pi/8$.')],[M('The midline is $(7-1)/2$ and the amplitude is $(7+1)/2$.'),A('$r=3$.'),A('$p=-4$, since the first extremum at $x=4$ is a minimum.')],[M('$\\sin(\\pi x/8)=-1/2$; consider the stated interval.'),A('$x=\\frac{28}{3},\\frac{44}{3}$.')]],svg_graph(lambda z:-4*math.sin(math.pi*z/8)+3,0,20,-2,8,[(4,-1,'(4,−1)'),(12,7,'(12,7)')]))
assert len(roots)==2
rpan,hpan=10,6;vol=math.pi*rpan*rpan*hpan;rs=(3*vol/(4*math.pi))**(1/3);coolA=160;room=22;target=50;base=1.6;tm=4*math.log(coolA/(target-room),base)
add(29,'Geometry and modelling','A cylindrical baking tin has diameter $20$ cm and height $6$ cm. A spherical ball of dough exactly fills the tin after being reshaped. After baking, its temperature is modelled by $T(t)=a(1.6)^{-t/4}+22$, where $t$ is the time in minutes after removal from the oven. Its initial temperature is $182^\\circ$C.',[('Find the volume of the tin.',2),('Find the radius of the original dough ball to one decimal place.',3),('Find $a$.',2),('Find when the temperature first falls to $50^\\circ$C.',3),('State the limiting temperature and interpret it.',3)],[[M('$V=\\pi r^2h$.'),A('$V=600\\pi\\text{ cm}^3$.')],[M('$\\frac43\\pi R^3=600\\pi$.'),A('$R^3=450$.'),A(f'$R={rs:.1f}$ cm.')],[M('$T(0)=a+22=182$.'),A('$a=160$.')],[M('$160(1.6)^{-t/4}=28$.'),M('$t=4\\ln(160/28)/\\ln1.6$.'),A(f'$t={N(tm)}$ minutes.')],[M('As $t\\to\\infty$, $(1.6)^{-t/4}\\to0$.'),A('$T\\to22^\\circ$C.'),RR('The model approaches room temperature without cooling below it.')]])
