add(30,'Triangle geometry','Triangle $ABC$ has $AC=12$ cm, $\\angle BAC=40^\\circ$ and area $30$ cm$^2$.',[('Find $AB$.',3),('Find $BC$.',3),('Find $\\angle ABC$.',2)],[[M('$30=\\frac12(12)(AB)\\sin40^\\circ$.'),A('$AB=5/\\sin40^\\circ$.'),A(f'$AB={N(c)}$ cm.')],[M('Use the cosine rule.'),A(f'$BC^2=12^2+({G(c)})^2-24({G(c)})\\cos40^\\circ$.'),A(f'$BC={N(a)}$ cm.')],[M('Use the cosine rule for $B$, avoiding the ambiguous sine inverse.'),A(f'$B={N(angB)}^\\circ$.')]])
