def crossarea(n,a,b,marks=(2,2)):
 u,v=S.Matrix(a),S.Matrix(b);w=cross(u,v);ar=norm(w)/2;assert dot(w,u)==0 and dot(w,v)==0
 m1,m2=marks;s1=[M('Expand the cross-product determinant.'),A(f'$\\overrightarrow{{OA}}\\times\\overrightarrow{{OB}}={V(w)}$.',m1-1)];s2=[M('Triangle area is half the cross-product magnitude.'),A(f'$K={L(ar)}$ square units.',m2-1)]
 add(n,'Vector products and areas',f'Points $A$ and $B$ have position vectors ${V(u)}$ and ${V(v)}$.',[('Find $\\overrightarrow{OA}\\times\\overrightarrow{OB}$.',m1),('Hence find the exact area of $OAB$.',m2)],[s1,s2])
