def intersect_lines(n,p,d,q,e,angleMode='lines'):
 p,d,q,e=map(S.Matrix,[p,d,q,e]);tt,ss=S.symbols('t s');res=S.solve(p+tt*d-q-ss*e,[tt,ss]);assert res and p+res[tt]*d==q+res[ss]*e;pt=p+res[tt]*d;ang=math.degrees(math.acos(float(abs(dot(d,e))/(norm(d)*norm(e))))) if angleMode=='lines' else math.degrees(math.acos(float(abs(dot(pt,d))/(norm(pt)*norm(d)))))
 add(n,'Vectors, points and lines',f'$A{P(p)}$ and $B{P(p+d)}$ define line $L_1$. Line $L_2$ is $\\mathbf r={V(q)}+s{V(e)}$.',[('Find $\\overrightarrow{AB}$ and a vector equation of $L_1$.',2),('Find the intersection point $C$.',3),(('Find the acute angle between the two lines.' if angleMode=='lines' else 'Find the acute angle between $OC$ and $L_1$.'),3)],[[A(f'$AB={V(d)}$.'),A(f'$L_1:\\mathbf r={V(p)}+t{V(d)}$.')],[M('Equate the three corresponding components.'),A(f'$t={L(res[tt])},s={L(res[ss])}$.'),A(f'$C{P(pt)}$.')],[M('Use the scalar-product formula with an absolute numerator for the acute angle.'),A('$\\cos\\theta='+L(abs(dot(d,e))/(norm(d)*norm(e)) if angleMode=='lines' else abs(dot(pt,d))/(norm(pt)*norm(d)))+'$.'),A(f'$\\theta={N(ang)}^\\circ$.')]])
