# Annular-sector optimization, including domain checks.
a0,b0=10,180
area_fn=lambda th:.5*th*(((b0+2*a0-a0*th)/(th+2))**2-a0*a0)
opt=minimize_scalar(lambda th:-area_fn(th),bounds=(1e-8,math.pi),method='bounded');optth=opt.x;optr=(b0+2*a0-a0*optth)/(optth+2)
rfix,areaFix=80,4000
fence=lambda aa:(rfix+aa)*2*areaFix/(rfix*rfix-aa*aa)+2*(rfix-aa)
upper=math.sqrt(rfix*rfix-2*areaFix/math.pi);opt2=minimize_scalar(fence,bounds=(0,upper),method='bounded');assert opt2.success
