# Complete medium reference sequence, preserving the tested constructions.
def polygon_svg(points,edges,labels=None,extras=''):
 labels=labels or {}; out=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 320" role="img">','<rect width="480" height="320" fill="white"/>']
 for u,v in edges:
  a,b=points[u],points[v];out.append(f'<line x1="{a[0]}" y1="{a[1]}" x2="{b[0]}" y2="{b[1]}" stroke="#334155" stroke-width="2"/>')
 for name,(xx,yy) in points.items():out.append(f'<circle cx="{xx}" cy="{yy}" r="3" fill="#0f172a"/><text x="{xx+7}" y="{yy-8}" font-size="16" fill="#0f172a">{html.escape(labels.get(name,name))}</text>')
 return ''.join(out)+extras+'</svg>'
