add(116,'Circle modelling','A circular field has centre $O$ and radius $350$ m. Points $A,B,C$ occur in that order anticlockwise, with $\\angle AOB=1.4$ radians and $\\angle BOC=2.3$ radians. The planted region consists of the minor segment between chord $AB$ and arc $AB$, together with the sector $BOC$.',[('Find chord $AB$.',3),('Find the area of triangle $AOB$.',2),('Find the length of the minor arc $AC$.',3),('Find the area of the planted region.',3),('Seed costs $155 per bag, and each bag covers $8500$ m$^2$. Find the minimum total cost.',4)],[[M('Bisect the isosceles triangle.'),A('$AB=700\\sin0.7$.'),A(f'$AB={N(700*math.sin(.7))}$ m.')],[M('$K=\\frac12r^2\\sin1.4$.'),A(f'$K={N(.5*r*r*math.sin(u))}$ m$^2$.')],[M('The other arc subtends $2\\pi-1.4-2.3$.'),A(f'Its angle is ${minor:.8f}$ radians, less than $\\pi$.'),A(f'Arc length $=350(2\\pi-3.7)={N(r*minor)}$ m.')],[M('Add sector $BOC$ to sector $AOB$ minus triangle $AOB$.'),A('$K_P=\\frac12(350)^2(3.7-\\sin1.4)$.'),A(f'$K_P={N(crop)}$ m$^2$.')],[M('Divide the unrounded planted area by $8500$.'),A(f'Number of bags before rounding $={crop/8500:.8f}$.'),RR(f'Round upwards to ${bags}$ whole bags.'),A(f'Cost $={bags}\\times155=\\${bags*155}$.')]],note='Explicit planted-region definition replaces partly unreadable source shading. All geometry and ceiling operation checked using unrounded values.')
