add(117,'Vector lines and lengths',f'$A={P(pa)}$, $B={P(pb)}$, and $\\overrightarrow{{AC}}={V(ac)}$. A line $L$ passes through $B$ parallel to $AC$.',[('Find $\\overrightarrow{AB}$.',2),('Find $C$.',2),('Give a vector equation of $L$.',1),('Find $k>0$ such that $|AB|=k|AC|$.',3),('Find both points $D$ on $L$ satisfying $|BD|=|AB|$.',4)],[[M('Subtract the position vector of $A$ from that of $B$.'),A(f'$\\overrightarrow{{AB}}={V(ab)}$.')],[M('$\\mathbf c=\\mathbf a+\\overrightarrow{AC}$.'),A(f'$C={P(pc)}$.')],[A(f'$\\mathbf r={V(pb)}+t{V(ac)}$, $t\\in\\mathbb R$.')],[A(f'$|AB|={L(norm(ab))}$.'),A(f'$|AC|={L(norm(ac))}$.'),A(f'$k={L(k)}$.')],[M('$D=B+t\\overrightarrow{AC}$, so $|BD|=|t||AC|$.'),A(f'$t=\\pm {L(k)}$.'),A(f'$D_1={P(pb+k*ac)}$.'),A(f'$D_2={P(pb-k*ac)}$.')]])
