add(118,'Sectors and grazing area','A goat is tied outside a triangular fence $ABC$, at $D$ on side $BC$. The rope is $7.5$ m long, $DC=2.5$ m, $AC=3.5$ m, $\\angle ACB=\\pi/3$, and $\\angle ABC=\\alpha$. The rope can wrap around $C$ and then $A$ but cannot reach $B$. The three accessible sectors do not overlap. The total grazing area is $116$ m$^2$.',[('Find $\\alpha$ in radians.',6)],[[A('The sector at $D$ is a semicircle of radius $7.5$.'),A('After wrapping around $C$, the remaining rope is $5$ m and the accessible angle is $2\\pi/3$.'),M('After also wrapping around $A$, the remaining rope is $1.5$ m; its sector angle is $\\pi-(2\\pi/3-\\alpha)=\\pi/3+\\alpha$.'),A('$116=\\frac12\\pi(7.5)^2+\\frac12(5)^2(2\\pi/3)+\\frac12(1.5)^2(\\pi/3+\\alpha)$.'),M('Rearrange the linear equation for $\\alpha$.'),A(f'$\\alpha={N(alpha)}$ radians.')]],polygon_svg({'A':(200,65),'B':(40,255),'C':(410,255),'D':(330,255)},[('A','B'),('B','C'),('C','A')],extras='<text x="305" y="145" font-size="15">3.5 m</text><text x="350" y="285" font-size="15">2.5 m</text><text x="350" y="237" font-size="15">π/3</text><text x="84" y="240" font-size="15">α</text>'),note='Grazing sectors reconstructed from the visible triangular-fence diagram. Computed alpha and checked via sine rule that BD exceeds 7.5 m, so the assumed wrap path is valid.')
add(119,'Vector magnitudes','Let $\\mathbf u=(-5,12)$ and $|\\mathbf v|=26$.',[('Find the possible range of $|\\mathbf u+\\mathbf v|$.',2),('If $\\mathbf v=k\\mathbf u$, find $\\mathbf v$ giving the minimum sum magnitude.',2),('Find $\\mathbf w=(a,b)$ with $a,b>0$, $|\\mathbf w|=26$ and $\\mathbf w\\perp\\mathbf u$.',5)],[[M('Use $||v|-|u||\\le|u+v|\\le|u|+|v|$, with $|u|=13$.'),A('$13\\le|u+v|\\le39$.')],[M('Choose the opposite direction with twice the magnitude.'),A('$\\mathbf v=-2\\mathbf u=(10,-24)$.')],[M('$-5a+12b=0$.'),A('$b=5a/12$.'),M('$a^2+b^2=26^2$.'),A('$a^2(169/144)=676$, hence $a=24$ using positivity.'),A('$b=10$, so $\\mathbf w=(24,10)$.')]])
add(120,'Vector proofs','The non-collinear points $P,Q,R$ have non-zero position vectors $\\mathbf p,\\mathbf q,\\mathbf r$. It is given that $\\mathbf p\\perp QR$ and $\\mathbf q\\perp RP$.',[('Prove that $\\mathbf r\\perp PQ$.',6)],[[A('$\\mathbf p\\cdot(\\mathbf r-\\mathbf q)=0$.'),A('$\\mathbf q\\cdot(\\mathbf p-\\mathbf r)=0$.'),M('Expand both scalar products.'),A('$\\mathbf p\\cdot\\mathbf r=\\mathbf p\\cdot\\mathbf q=\\mathbf q\\cdot\\mathbf r$.'),M('Use symmetry and subtract to obtain $\\mathbf r\\cdot(\\mathbf q-\\mathbf p)=0$.'),RR('Since $\\overrightarrow{PQ}=\\mathbf q-\\mathbf p$, this proves the required perpendicularity.')]])
add(121,'Exact trigonometry','Give all answers exactly.',[('Expand $(2+2\\sqrt3)^2$.',1),('Use $75^\\circ=30^\\circ+45^\\circ$ to find $\\cos75^\\circ$.',3),('In triangle $ABC$, $BC=2\\sqrt6$ cm, $CA=4$ cm and $\\angle ACB=75^\\circ$. Find $AB$ in the form $a+b\\sqrt3$ with integers $a,b>0$.',4)],[[A('$(2+2\\sqrt3)^2=16+8\\sqrt3$.')],[M('$\\cos(30^\\circ+45^\\circ)=\\cos30^\\circ\\cos45^\\circ-\\sin30^\\circ\\sin45^\\circ$.'),A('$=\\sqrt6/4-\\sqrt2/4$.'),A('$\\cos75^\\circ=(\\sqrt6-\\sqrt2)/4$.')],[M('Use the cosine rule.'),A('$AB^2=24+16-16\\sqrt6(\\sqrt6-\\sqrt2)/4$.'),A('$AB^2=16+8\\sqrt3=(2+2\\sqrt3)^2$.'),A('$AB=2+2\\sqrt3$ cm, taking the positive square root.')]])
