add(122,'Perpendicular vector lines',f'Lines $L_1$ and $L_2$ have equations $\\mathbf r={V(p)}+t{V(d)}$ and $\\mathbf r={V(q)}+s\\begin{{pmatrix}}1\\\\2\\\\k\\end{{pmatrix}}$. They are perpendicular and intersect at $A$.',[('Find $k$.',2),('Find the position vector of $A$.',3),(f'Given $B={P(pb)}$ and $\\overrightarrow{{BC}}={V(bcv)}$, find $\\overrightarrow{{BA}}$ and $\\angle CBA$.',4)],[[M('Set the scalar product of the direction vectors to zero.'),A('$2+2k=0$, so $k=-1$.')],[M('Equate the components of the two lines.'),A(f'$s={L(ts[S.Symbol("s")])}$, $t={L(ts[S.Symbol("t")])}$.'),A(f'$\\overrightarrow{{OA}}={V(pa)}$.')],[A(f'$\\overrightarrow{{BA}}={V(ba)}$.'),M('Use $\\overrightarrow{BA}\\cdot\\overrightarrow{BC}$.'),A('The scalar product is $0$.'),A('$\\angle CBA=90^\\circ$.')]])
add(123,'Exact trigonometry','Given $\\csc\\theta=-17/8$ and $\\pi/2<\\theta<3\\pi/2$, find $\\cot\\theta$.',[('Find the exact value.',4)],[[A('$\\sin\\theta=-8/17$.'),RR('The negative sine in the interval places $\\theta$ in quadrant III.'),A('$\\cos\\theta=-\\sqrt{1-64/289}=-15/17$.'),A('$\\cot\\theta=15/8$.')]])
