add(124,'Intersecting circles','Two circles of radii $6$ cm and $3$ cm have centres $A$ and $B$. They intersect at $S$ and $T$, with $\\angle SAT=40^\\circ$. The centres lie on opposite sides of the common chord $ST$. The lens is their shared interior.',[('Find $ST$.',2),('Find the area of the lens.',5)],[[M('$ST=12\\sin20^\\circ$.'),A(f'$ST={N(ch)}$ cm.')],[M('Find the minor central angle at $B$ from $ST=6\\sin(\\beta/2)$.'),A(f'$\\beta=2\\arcsin(2\\sin20^\\circ)={be:.8f}$ radians.'),M('The lens is the sum of the two minor segments.'),A('$K=18(2\\pi/9-\\sin(2\\pi/9))+\\frac92(\\beta-\\sin\\beta)$.'),A(f'$K={N(lens)}$ cm$^2$.')]])
add(125,'Trigonometric graphs','Let $f(x)=a\\sin(bx)+c$ for $0\\le x\\le2\\pi$, with $b>0$. Consecutive stationary points are a minimum at $(\\pi/4,1)$ and a maximum at $(3\\pi/4,7)$.',[('Find $a,b,c$.',5),('Find the largest $k$ for which the restriction of $f$ to $[3\\pi/4,k]$ has an inverse.',2),('For $g(x)=-2f(x/2)+5$, find its first maximum with $x>0$.',3)],[[A('Midline $c=(7+1)/2=4$.'),A('Amplitude $|a|=(7-1)/2=3$.'),M('Consecutive minimum and maximum are half a period apart.'),A('$T=\\pi$, so $b=2$.'),A('$\\sin(2\\cdot\\pi/4)=1$ at the minimum, so $a=-3$.')],[M('Stop at the next stationary point so the function remains one-to-one.'),A('$k=5\\pi/4$.')],[M('$g(x)=6\\sin x-3$.'),A('First positive maximum occurs at $x=\\pi/2$.'),A('Maximum point $(\\pi/2,3)$.')]],note='Source graph reconstructed through explicitly specified consecutive stationary points. Frequencies and inverse interval checked algebraically.')
