add(126,'Intersection of planes','The planes $x-2y+2z=2$, $2x+y+z=d$ and $3x-y+cz=7$ have a common line of intersection. Assume their first two normals are independent.',[('Find $c$ and $d$.',4),('Find the shortest distance from the origin to this line.',3)],[[M('The third normal must be a linear combination of the first two.'),A('The $x,y$ components force both coefficients to be $1$.'),A('$c=2+1=3$.'),A('The constants must obey $7=2+d$, hence $d=5$.')],[M('The closest point has position in the span of the two normals and satisfies both plane equations.'),A(f'This point is ${P(foot)}$.'),A(f'Distance $={L(dist)}\\approx{N(dist)}$.')]])
add(127,'Points on vector lines','A line passes through $A(4,3,1)$ and $B(6,4,2)$. Point $C(0,b,-1)$ lies on this line. Point $D(p^2,-4,3p)$ is such that $CD$ is perpendicular to the line.',[('Find $b$.',3),('Find all possible values of $p$.',5)],[[M('The line is $(4,3,1)+t(2,1,1)$.'),A('The $x$ component gives $t=-2$, consistent with $z=-1$.'),A('$b=3-2=1$.')],[A('$\\overrightarrow{CD}=(p^2,-5,3p+1)$.'),M('Set its scalar product with $(2,1,1)$ to zero.'),A('$2p^2+3p-4=0$.'),M('Apply the quadratic formula.'),A('$p=(-3\\pm\\sqrt{41})/4$.')]])
add(128,'Trigonometric equations','Solve $\\cos2x+2\\cos x=1+\\sin2x-2\\sin x$ for $-\\pi\\le x\\le\\pi$.',[('Find all solutions exactly.',6)],[[M('Use $\\cos2x=1-2\\sin^2x$ and $\\sin2x=2\\sin x\\cos x$.'),A('$-2\\sin^2x+2\\cos x-2\\sin x\\cos x+2\\sin x=0$.'),M('Factor the expression.'),A('$2(\\cos x+\\sin x)(1-\\sin x)=0$.'),A('$\\sin x=1$ gives $x=\\pi/2$; $\\tan x=-1$ gives $x=-\\pi/4,3\\pi/4$.'),A('Complete solution set $\\{-\\pi/4,\\pi/2,3\\pi/4\\}$.')]])
