add(130,'Projection and reflection',f'The line $L$ is $\\mathbf r={V(p)}+t{V(d)}$. The point $A$ has coordinates ${P(pa)}$.',[('Find the foot $N$ of the perpendicular from $A$ to $L$.',4),('Find the shortest distance from $A$ to $L$.',2),('Find the reflection of $A$ in $L$.',2)],[[M('$N=p+td$ and $(N-A)\\cdot d=0$.'),A('$t='+L(t0)+'$.'),A(f'$N={P(foot)}$.'),RR('This point lies on $L$ and its displacement from $A$ is orthogonal to the line direction.')],[M('Find $|A-N|$.'),A(f'Distance $={L(dist)}$.')],[M('$N$ is the midpoint of $A$ and its image, so $A^{\\prime}=2N-A$.'),A(f'$A^{{\\prime}}={P(reflection)}$.')]])
