add(132,'Trigonometric transformations','Let $g(x)=-3x-\\pi/4$, $h(x)=4\\cos x+2$, and $F=h\\circ g$.',[('Find the range of $F$.',2),('Find the first two positive $x$ values at which $F$ is maximum.',3),('Describe a sequence of five transformations taking $y=\\cos x$ to $y=F(x)$.',5)],[[M('Cosine ranges from $-1$ to $1$.'),A('Range $[-2,6]$.')],[M('Maximum occurs when $-3x-\\pi/4=2k\\pi$.'),A('The first positive solution is $7\\pi/12$.'),A('The next is $5\\pi/4$.')],[A('Reflect in the $y$-axis.'),A('Compress horizontally by factor $1/3$.'),A('Translate left by $\\pi/12$.'),A('Stretch vertically by factor $4$.'),A('Translate upwards by $2$. This produces $4\\cos[-3(x+\\pi/12)]+2$.')]])
