add(135,'Circle modelling','A rectangular paddock measures $14$ m by $6$ m. A goat is tethered at one corner, and the rope stays inside the paddock. First the rope length is $7$ m.',[('Find the percentage of the paddock that the goat can graze.',5),('For a rope of length $a$ with $6<a<14$, show that grazing $75%$ of the paddock requires $6\\sqrt{a^2-36}+a^2\\arcsin(6/a)=126$.',5),('Find $a$.',2)],[[M('Integrate the quarter-circle region up to height $6$, or split it into a sector and right triangle.'),A('$K=\\frac12[6\\sqrt{7^2-6^2}+7^2\\arcsin(6/7)]$.'),A(f'$K={area(r0):.8f}$ m$^2$.'),M('Divide by paddock area $84$ and multiply by $100$.'),A(f'Grazed percentage $={N(100*area(r0)/84)}\\%$.')],[M('For general $a$, use the same sector-plus-triangle decomposition.'),A('The sector angle is $\\arcsin(6/a)$.'),A('The triangle has legs $6$ and $\\sqrt{a^2-36}$.'),A('$K=\\frac12[6\\sqrt{a^2-36}+a^2\\arcsin(6/a)]$.'),A('Set $K=0.75(84)=63$ and multiply by $2$.')],[M('Solve the displayed equation numerically on $(6,14)$.'),A(f'$a={N(rr)}$ m.')]],note='Circle/rectangle clipping formula checked by numerical root solving; solution lies below the longer side, so no second-edge correction is needed.')
