add(136,'Related rates and sectors','A sector of radius $r$ and angle $0<\\theta<\\pi$ is symmetric about a vertical line through its centre $O$. Its tight bounding rectangle has height $r$ and width equal to the chord joining the sector endpoints. Let the rectangle area be $A$.',[('Show that $A=r\\sqrt{2r^2(1-\\cos\\theta)}$.',2),('The radius is fixed at $6$ cm and $d\\theta/dt=1/3$ rad/s. Find $dA/dt$ when $\\theta=\\pi/3$.',4)],[[M('The width is $2r\\sin(\\theta/2)$, so $A=2r^2\\sin(\\theta/2)$.'),A('Use $\\sin(\\theta/2)=\\sqrt{(1-\\cos\\theta)/2}$ on the stated interval.')],[M('Differentiate $A=72\\sin(\\theta/2)$ with respect to $t$.'),A('$dA/dt=36\\cos(\\theta/2)\\,d\\theta/dt$.'),A('At $\\theta=\\pi/3$, this is $12\\cos(\\pi/6)$.'),A('$dA/dt=6\\sqrt3$ cm$^2$/s.')]],diag)
add(137,'Logarithmic trigonometric equations','Use exact values.',[('Show that $\\log_5\\sqrt{\\cos2x+3}=\\log_{25}(\\cos2x+3)$.',3),('Hence solve $\\log_5(\\sqrt6\\cos x)=\\log_{25}(\\cos2x+3)$ for $0<x<\\pi/2$.',5)],[[M('Apply the power rule to the square root.'),A('The left side is $\\tfrac12\\log_5(\\cos2x+3)$.'),A('Change of base gives $\\log_{25}u=\\log_5u/2$.')],[M('Use part (a) and injectivity of the logarithm.'),A('$\\sqrt6\\cos x=\\sqrt{\\cos2x+3}$.'),M('Square, which is reversible because both sides are positive.'),A('$6\\cos^2x=2\\cos^2x+2$, giving $\\cos^2x=1/2$.'),A('$x=\\pi/4$.')]])
add(138,'Algebraic trigonometric equations','Consider the rational expression below.',[('Show that $2u-5+3/(u+1)=(2u^2-3u-2)/(u+1)$ for $u\\ne-1$.',2),('Hence solve $2\\sin2\\theta-5+3/(\\sin2\\theta+1)=0$ for $0\\le\\theta\\le\\pi$.',5)],[[M('Put all terms over $u+1$.'),A('$(2u-5)(u+1)+3=2u^2-3u-2$.')],[M('The numerator must be zero and the denominator non-zero.'),A('$(2\\sin2\\theta+1)(\\sin2\\theta-2)=0$.'),RR('$\\sin2\\theta=2$ is impossible, so $\\sin2\\theta=-1/2$.'),A('$2\\theta=7\\pi/6,11\\pi/6$.'),A('$\\theta=7\\pi/12,11\\pi/12$; neither makes the denominator zero.')]])
