add(142,'Skew lines and planes',f'Let $A={P(pa)}$, $B={P(pb)}$, $C={P(pc)}$. Line $L_1$ passes through $C$ parallel to $AB$. Line $L_2$ has Cartesian form $(x+1)/3=y=(z-2)/(-2)$.',[('Find $\\overrightarrow{AB}$ and a vector equation of $L_1$ using $\\lambda$.',3),('Write $L_2$ in vector form using $\\mu$.',2),('For $D\\in L_1$ and $E\\in L_2$, express $\\overrightarrow{DE}$ in terms of $\\lambda,\\mu$, and find the minimum distance between the lines.',9),('Find the plane $ABC$ and the area of the triangle formed by its $y,z$ intercepts and the origin.',8)],[[A(f'$\\overrightarrow{{AB}}={V(d)}$.'),M('Use $C$ as a point and $AB$ as direction.'),A(f'$L_1: \\mathbf r={V(pc)}+\\lambda{V(d)}$.')],[M('Set the common Cartesian ratio equal to $\\mu$.'),A(f'$L_2: \\mathbf r={V(q)}+\\mu{V(e)}$.')],[M('Subtract $D$ from $E$.'),A(f'$\\overrightarrow{{DE}}={V(rel)}$.'),M('At the shortest connector, $DE$ is perpendicular to both direction vectors.'),A('$\\overrightarrow{DE}\\cdot'+V(d)+'=0$.'),A('$\\overrightarrow{DE}\\cdot'+V(e)+'=0$.'),M('Solve these two linear equations simultaneously.'),A(f'$\\lambda={L(sol[lam])}$, $\\mu={L(sol[mu])}$.'),A(f'The shortest connector is ${V(short)}$.'),A(f'Minimum distance $={L(dist)}\\approx{N(dist)}$.')],[A(f'$\\overrightarrow{{AC}}={V(pc-pa)}$.'),M('Find the cross product of $AB$ and $AC$.'),A(f'A normal vector is ${V(normal)}$.'),A('$\\Pi: '+eqplane(normal,pa)+'$.'),M('Set $x=z=0$ for the $y$ intercept and $x=y=0$ for the $z$ intercept.'),A(f'Intercepts $(0,{L(yi)},0)$ and $(0,0,{L(zi)})$.'),M('The two intercept axes are perpendicular, so area is half the product of absolute intercepts.'),A(f'Area $={L(areaYZ)}\\approx{N(areaYZ)}$.')]])
add(143,'Logarithmic trigonometric equations','Use exact values.',[('Show that $\\log_3\\sqrt{4-\\cos2x}=\\log_9(4-\\cos2x)$.',3),('Hence solve $\\log_9(2\\sin x)+1/2=\\log_3\\sqrt{4-\\cos2x}$ for $0<x<\\pi/2$.',5)],[[M('Apply the power law to the square root.'),A('The left side is $\\frac12\\log_3(4-\\cos2x)$.'),A('Changing base from $3$ to $9$ gives the required identity.')],[M('Use part (a) and combine $1/2=\\log_9 3$.'),A('$6\\sin x=4-\\cos2x$.'),M('Put $s=\\sin x$ and use $\\cos2x=1-2s^2$.'),A('$2s^2-6s+3=0$, hence $s=(3\\pm\\sqrt3)/2$.'),A('Only $(3-\\sqrt3)/2$ lies in $(0,1)$, so $x=\\arcsin[(3-\\sqrt3)/2]$.')]])
