# A pole-aware sketch for the rational function, with separately sampled branches.
def rational_sketch():
 W,H=560,340;X=lambda z:45+(z+10)/16*480;Y=lambda z:280-(z+3)/7*240
 out=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 560 340"><rect width="560" height="340" fill="white"/>']
 for xx in [-6,2]:out.append(f'<line x1="{X(xx)}" y1="30" x2="{X(xx)}" y2="300" stroke="#dc2626" stroke-dasharray="6 4"/><text x="{X(xx)+4}" y="318" font-size="14">x = {xx}</text>')
 out.extend([f'<line x1="40" y1="{Y(0)}" x2="535" y2="{Y(0)}" stroke="#64748b"/>',f'<line x1="{X(0)}" y1="20" x2="{X(0)}" y2="300" stroke="#64748b"/>'])
 for a,b in [(-10,-6.1),(-5.9,1.9),(2.1,6)]:
  points=[]
  for i in range(300):
   xx=a+(b-a)*i/299;yy=9/(xx*xx+4*xx-12)
   if -3<=yy<=4:points.append(f'{X(xx):.2f},{Y(yy):.2f}')
  out.append('<polyline points="'+' '.join(points)+'" fill="none" stroke="#2563eb" stroke-width="2"/>')
 for xx,yy,label in [(-2,-9/16,'(-2, -9/16)'),(0,-.75,'(0, -3/4)')]:out.append(f'<circle cx="{X(xx)}" cy="{Y(yy)}" r="3" fill="#0f172a"/><text x="{X(xx)+6}" y="{Y(yy)+18}" font-size="13">{label}</text>')
 out.append(f'<text x="460" y="{Y(0)-8}" font-size="13">y = 0</text></svg>');return ''.join(out)
add(159,'Rational inverses and trigonometry','Let $f(x)=9/(x^2+4x-12)$, with $x\\ne-6,2$. Let $g$ be the restriction of $f$ to $x>2$, and let $h(x)=\\arccos(x/9)$.',[('Sketch $f$, labelling intercepts, stationary points and asymptotes.',6),('Find an expression for $g^{-1}(x)$.',6),('State the domain of $g^{-1}$.',1),('Given $(h\\circ g)(a)=\\pi/3$, find $a$ in the form $p+q\\sqrt2$.',7)],[[A('Vertical asymptotes $x=-6$ and $x=2$.'),A('Horizontal asymptote $y=0$.'),A('$y$ intercept $(0,-3/4)$; no $x$ intercepts.'),M('$f^{\\prime}(x)=-18(x+2)/(x^2+4x-12)^2$.'),A('Local maximum at $(-2,-9/16)$.'),A('Three correctly oriented branches: positive outside the poles, negative between them, tending to the stated asymptotes.')],[M('Write $y=9/[(x+2)^2-16]$.'),A('$(x+2)^2=16+9/y$.'),A('$x+2=\\pm\\sqrt{16+9/y}$.'),RR('Since $x>2$, choose the positive square root.'),A('$x=-2+\\sqrt{16+9/y}$.'),A('$g^{-1}(x)=-2+\\sqrt{(16x+9)/x}$.')],[A('Domain $(0,\\infty)$.')],[M('$\\arccos(g(a)/9)=\\pi/3$ implies $g(a)/9=1/2$.'),A('$g(a)=9/2$.'),M('$9/(a^2+4a-12)=9/2$.'),A('$a^2+4a-14=0$.'),M('Complete the square: $(a+2)^2=18$.'),A('$a=-2\\pm3\\sqrt2$.'),A('$a=-2+3\\sqrt2$, since $a>2$.')]],msdiagram=rational_sketch())
