add(160,'Parallel plane and line',f'Three planes are $2x+y-z={k1}$, $x+4y-4z={k2}$ and $3x+4y-4z={k3}$. Let $L$ be the intersection of the first two.',[('Show that all three planes have no common point.',4),(f'Given that $Q={P(p)}$ lies on the first two planes, find $L$.',4),('Show that $L$ is parallel to the third plane.',2),('Find the distance between $L$ and the third plane.',5)],[[M('Put $w=y-z$ in the first two equations.'),A('$2x+w=-5$, $x+4w=-6$.'),A('Solving gives $x=-2$, $w=-1$.'),RR('The third left side is then $3(-2)+4(-1)=-10$, which differs from $-8$; no common point exists.')],[M('Take the cross product of the first two plane normals.'),A('A direction vector is $(0,1,1)$.'),A(f'Use point $Q={P(p)}$.'),A(f'$L:\\mathbf r={V(p)}+t{V(d)}$.')],[M('Take the scalar product of the line direction and third-plane normal.'),A('$(0,1,1)\\cdot(3,4,-4)=0$, so the line is parallel to the plane.')],[M('Every point on the parallel line has the same distance from the plane; use $Q$.'),A('Normal magnitude $=\\sqrt{41}$.'),A('Absolute plane residual at $Q$ is $|-10+8|=2$.'),M('Divide the residual by the normal magnitude.'),A('$d=2/\\sqrt{41}=2\\sqrt{41}/41$.')]])
# Barycentric ratios chosen so the concurrency condition is exact.
add(161,'Vector ratios and collinearity','In triangle $ABC$, points satisfy $AN=\\tfrac25AB$, $BR=\\tfrac12BC$, $CS=\\tfrac13CA$, and $RT=\\tfrac9{13}RS$. Position vectors of $A,B,C$ are $\\mathbf a,\\mathbf b,\\mathbf c$.',[('Express $AN$ and $CN$ in terms of $\\mathbf a,\\mathbf b,\\mathbf c$.',4),('Express $RC$, $CS$, and $RT$ in terms of the position vectors.',5),('Prove that $T$ lies on segment $CN$.',5)],[[A('$AN=\\frac25(\\mathbf b-\\mathbf a)$.'),M('$\\mathbf n=\\mathbf a+AN$.'),A('$\\mathbf n=\\frac35\\mathbf a+\\frac25\\mathbf b$.'),A('$CN=\\frac35\\mathbf a+\\frac25\\mathbf b-\\mathbf c$.')],[A('$RC=\\frac12(\\mathbf c-\\mathbf b)$.'),A('$CS=\\frac13(\\mathbf a-\\mathbf c)$.'),M('$RS=RC+CS$.'),A('$RS=\\frac13\\mathbf a-\\frac12\\mathbf b+\\frac16\\mathbf c$.'),A('$RT=\\frac3{13}\\mathbf a-\\frac9{26}\\mathbf b+\\frac3{26}\\mathbf c$.')],[M('$CT=CR+RT$, with $CR=\\frac12(\\mathbf b-\\mathbf c)$.'),A('$CT=\\frac3{13}\\mathbf a+\\frac2{13}\\mathbf b-\\frac5{13}\\mathbf c$.'),M('Compare coefficients with $CN$.'),A('$CT=\\frac5{13}CN$.'),RR('The coefficient lies strictly between $0$ and $1$, so $T$ lies on segment $CN$.')]],polygon_svg({'A':(235,35),'B':(50,275),'C':(430,275),'N':(161,131),'R':(240,275),'S':(365,195),'T':(326.54,219.62)},[('A','B'),('B','C'),('C','A'),('C','N'),('R','S')]))
