add(162,'Line-plane angles','Plane $\\Pi$ has equation $x+y+2z=7$. A line has equation $\\mathbf r=(3,2,-1)+t(-1,1,p)$. The acute angle between the line and plane is $45^\\circ$.',[('Find all possible $p$.',7)],[[A('Plane normal $(1,1,2)$ and line direction $(-1,1,p)$.'),M('Use $\\sin45^\\circ=|n\\cdot d|/(|n||d|)$.'),A('$1/\\sqrt2=|2p|/(\\sqrt6\\sqrt{p^2+2})$.'),M('Square both sides.'),A('$3(p^2+2)=4p^2$.'),A('$p^2=6$.'),A('$p=\\pm\\sqrt6$; both satisfy the original absolute-value equation.')]])
add(163,'Triple-angle polynomial roots','Angles in this question are in degrees. Let $f(x)=32x^3-6x-\\cos3k$, where $0^\\circ\\le k\\le360^\\circ$.',[('Prove $\\cos3\\theta=4\\cos^3\\theta-3\\cos\\theta$.',4),('Verify that $\\tfrac12\\cos k$ is a root of $f$.',2),('If the other roots are $\\alpha,\\beta$, find $\\alpha\\beta$ and $\\alpha+\\beta$.',3),('Show that $\\alpha^2+\\tfrac12\\alpha\\cos k+\\tfrac14\\cos^2k-\\tfrac3{16}=0$.',2),('Find expressions for $\\alpha$ and $\\beta$.',4),('Find every $k$ for which the graph of $f$ meets the $x$ axis at exactly two distinct points.',7)],[[M('Expand $\\cos(2\\theta+\\theta)$.'),A('$\\cos3\\theta=(2\\cos^2\\theta-1)\\cos\\theta-2\\sin^2\\theta\\cos\\theta$.'),M('Substitute $\\sin^2\\theta=1-\\cos^2\\theta$.'),A('Collect terms to obtain $4\\cos^3\\theta-3\\cos\\theta$.')],[M('Substitute $x=\\cos k/2$.'),A('$f(\\cos k/2)=4\\cos^3k-3\\cos k-\\cos3k=0$.')],[A('Sum of roots $0$, so $\\alpha+\\beta=-\\cos k/2$.'),M('The pairwise product sum is $-6/32=-3/16$.'),A('$\\alpha\\beta=\\cos^2k/4-3/16$.')],[M('Use $\\alpha^2-(\\alpha+\\beta)\\alpha+\\alpha\\beta=0$.'),A('Substituting the expressions from part (c) gives the stated quadratic.')],[M('Apply the quadratic formula.'),A('The discriminant is $3\\sin^2k/4$.'),A('The two roots are $[-\\cos k\\pm\\sqrt3\\sin k]/4$.'),RR('Assign the plus expression to $\\alpha$ and the minus expression to $\\beta$; when sine is negative this only interchanges their labels.')],[M('Exactly two distinct roots occur when any two of the three roots coincide.'),A('$\\alpha=\\beta$ requires $\\sin k=0$.'),A('This gives $k=0^\\circ,180^\\circ,360^\\circ$.'),M('Equating either other root to $\\cos k/2$ gives $\\tan k=\\pm\\sqrt3$.'),A('This gives $k=60^\\circ,120^\\circ,240^\\circ,300^\\circ$.'),RR('A triple root is impossible because the coefficient of $x$ is non-zero.'),A('Complete set: $0^\\circ,60^\\circ,120^\\circ,180^\\circ,240^\\circ,300^\\circ,360^\\circ$.')]])
