add(164,'Systems of three planes',f'Plane $\\Pi_1$ passes through $A={P(pa)}$, $B={P(pb)}$, $C={P(pc)}$. The other planes are $\\Pi_2:x+3y-2z=4$ and $\\Pi_3:-2x+ay+4z=-8$.',[('Find $\\Pi_1$.',5),('Find the value of $a$ giving infinitely many common solutions, describe the planes in that case, and give the common line in parametric form.',7),('Show that the three planes can never have a unique common point.',3),('Show that for $a>2$, their pairwise intersections are three distinct parallel lines.',4)],[[A('$AB=(2,0,1)$ and $AC=(1,-2,0)$.'),M('Take the cross product.'),A('$AB\\times AC=(2,1,-4)$.'),M('Substitute $A$ into the normal form.'),A('$\\Pi_1:2x+y-4z=5$.')],[M('The first two planes give $u=x-2z=11/5$ and $y=3/5$.'),A('Substitution in the third yields $-22/5+3a/5=-8$.'),A('$a=-6$.'),RR('Then $\\Pi_3$ is the same plane as $\\Pi_2$; both meet $\\Pi_1$ in a line.'),M('Let $z=t$.'),A('$x=11/5+2t$.'),A('$y=3/5$, $z=t$, with $t\\in\\mathbb R$.')],[A('Every plane normal is perpendicular to $(2,0,1)$.'),M('Therefore the coefficient matrix has rank at most $2$.'),RR('Three variables cannot then have a unique solution: the system is either inconsistent or has infinitely many solutions.')],[A('For $a>2$, no two plane normals are proportional (exceptional parallel cases are $a=-6,-1$).'),M('Thus each pair intersects in a line with direction $(2,0,1)$.'),RR('Part (b) shows there is no common point because $a\\ne-6$.'),RR('The three pairwise lines are consequently distinct and parallel.')]])
add(165,'Parallelogram scalar products','In non-degenerate parallelogram $ABCD$, let $AB=\\mathbf u$, $AD=\\mathbf v$, with $|u|=|v|/3$. Their angle is $\\alpha$. A point $X$ on $BC$ satisfies $BX=c\\mathbf v$, where $0\\le c\\le1$.',[('Express $XA$ and $XD$ using $u,v,c$.',3),('If $XA\\perp XD$, show that $9c^2+(6\\cos\\alpha-9)c+1-3\\cos\\alpha=0$.',4),('Find both possible $c$ when $\\alpha=\\pi/2$.',3)],[[A('$\\overrightarrow{AX}=\\mathbf u+c\\mathbf v$.'),A('$XA=-\\mathbf u-c\\mathbf v$.'),A('$XD=-\\mathbf u+(1-c)\\mathbf v$.')],[M('Set $(-u-cv)\\cdot[-u+(1-c)v]=0$.'),A('$|u|^2+(2c-1)u\\cdot v+c(c-1)|v|^2=0$.'),A('Use $|u|^2=|v|^2/9$ and $u\\cdot v=|v|^2\\cos\\alpha/3$.'),A('Divide by $|v|^2>0$ and multiply by $9$ to obtain the stated quadratic.')],[A('$9c^2-9c+1=0$.'),M('Apply the quadratic formula.'),A('$c=(3\\pm\\sqrt5)/6$; both lie in $[0,1]$.')]],polygon_svg({'A':(65,260),'B':(210,260),'C':(410,65),'D':(265,65),'X':(310,162.5)},[('A','B'),('B','C'),('C','D'),('D','A'),('A','X'),('D','X')],extras='<text x="130" y="288" font-size="16">u</text><text x="140" y="150" font-size="16">v</text>'),note='Source Q165 final part is absent; restored a 3-mark exact root application, retaining scalar-product geometry and changing the side-length ratio.')
