add(166,'Ambiguous triangles','In triangle $XYZ$, $XY=10$ cm, $YZ=x$ cm, $XZ=y$ cm and $\\angle XYZ=40^\\circ$.',[('Show that $x^2-20x\\cos40^\\circ+100-y^2=0$.',2),('Find the two possible $x$ values when $y=7$.',3),('Find the area of the smaller triangle.',3),('Find the range of $y$ for which two distinct triangles are possible.',7)],[[M('Apply the cosine rule to side $XZ$.'),A('$y^2=10^2+x^2-20x\\cos40^\\circ$; rearrange as required.')],[M('Substitute $y=7$ and solve the resulting quadratic.'),A(f'$x={roots[0]:.8f}$ or ${roots[1]:.8f}$ cm.'),A(f'To three significant figures: ${N(roots[0])}$ cm or ${N(roots[1])}$ cm.')],[M('$K=\\frac12(10)x\\sin40^\\circ$.'),A(f'Use the smaller root, $x={roots[0]:.8f}$.'),A(f'$K={N(5*roots[0]*math.sin(angle))}$ cm$^2$.')],[M('Two triangles require two distinct positive roots for $x$.'),A('Discriminant $\\Delta=4(y^2-100\\sin^240^\\circ)$.'),A('$\\Delta>0$ implies $y>10\\sin40^\\circ$.'),M('Both roots have positive sum $20\\cos40^\\circ$; they are both positive exactly when the product $100-y^2>0$.'),A('Thus $y<10$.'),RR('At either endpoint there is only one non-degenerate triangle, so both bounds are strict.'),A('$10\\sin40^\\circ<y<10$ cm.')]])
p=S.Matrix([2,5,4]);v=S.Matrix([-2,3,1]);q=S.Matrix([-3,1,1]);w=S.Matrix([3,-1,2]);r=p-q;dv=v-w;t0=-dot(r,dv)/dot(dv,dv);actual=norm(r+t0*dv);n=cross(v,w);path=abs(dot(r,n))/norm(n);ss,tt=S.symbols('s t');rel=q+tt*w-p-ss*v;pars=S.solve([dot(rel,v),dot(rel,w)],[ss,tt]);connector=rel.subs(pars)
add(167,'Motion and skew flight paths',f'Two display aircraft have positions $\\mathbf r_A={V(p)}+t{V(v)}$ and $\\mathbf r_B={V(q)}+t{V(w)}$, in metres for $0\\le t\\le2$ seconds. Their complete straight flight-path lines extend beyond this time interval.',[('Find when the aircraft are closest during this interval and their separation then.',5),('Show that the complete flight-path lines are skew and find the minimum distance between them.',12),('A display rule requires actual separation to exceed $5$ m. Does this motion satisfy the rule?',1)],[[M('Form the simultaneous relative position $r_A-r_B$.'),A('$D^2(t)='+L(dot(r+x*dv,r+x*dv)).replace('x','t')+'$.'),M('Minimize this positive quadratic on $[0,2]$.'),A(f'$t={L(t0)}$ seconds, which is in the interval.'),A(f'Minimum simultaneous separation $={L(actual)}\\approx{N(actual)}$ m.')],[A('The direction vectors are not proportional.'),M('For an intersection, equate $p+sv=q+uw$ using independent parameters.'),A(f'$v\\times w={V(n)}$.'),A(f'$(q-p)\\cdot(v\\times w)={dot(q-p,n)}\\ne0$.'),RR('The non-zero scalar triple product proves the two non-parallel lines are not coplanar; they are skew.'),M('For the shortest connector, its scalar products with $v$ and $w$ must both vanish.'),A(f'Write $DE={V(rel)}$.'),A('$DE\\cdot v=0$, $DE\\cdot w=0$.'),M('Solve the resulting two simultaneous linear equations.'),A(f'$s={L(pars[ss])}$, $t={L(pars[tt])}$ for independent path parameters.'),A(f'The connector is ${V(connector)}$.'),A(f'Minimum path separation $={L(path)}\\approx{N(path)}$ m.')],[RR(f'Yes: the actual minimum is ${N(actual)}>5$ m. The smaller geometric path distance occurs at different path parameters and does not represent a simultaneous aircraft separation.')]])
