add(168,'Closest points on lines',f'$L_1:\\mathbf r={V(p)}+t{V(d)}$ and $L_2:\\mathbf r={V(q)}+s{V(e)}$.',[('Find the point on $L_1$ nearest the origin.',4),('Find the shortest distance between the two lines.',7)],[[M('At the nearest point, its position vector is perpendicular to the line direction.'),A('$(p+td)\\cdot d=0$.'),A(f'$t={L(t0)}$.'),A(f'Nearest point ${P(foot)}$.')],[M('Find a vector perpendicular to both line directions.'),A(f'$n=d\\times e={V(n)}$.'),A(f'$q-p={V(q-p)}$.'),M('Project the joining vector onto this common normal.'),A('$D=|(q-p)\\cdot n|/|n|$.'),A(f'$D={L(abs(dot(q-p,n)))}/{L(norm(n))}$.'),A(f'$D={L(dist)}\\approx{N(dist)}$.')]])
