add(169,'Perpendicular lines and planes','Plane $\\Pi$ is $3x-y+2z=16$. Line $L$ is $\\mathbf r=(1,-p,2)+\\lambda(-6,2,p)$ and is perpendicular to $\\Pi$.',[('Find $p$.',2),('Find the intersection of $L$ and $\\Pi$.',3),('For $P=(4,-2,3)$, find the displacement $PA$ to a general point $A$ of $L$, the parameter of the perpendicular foot, the foot itself, and the shortest distance.',7),('Find a plane perpendicular to both $3x-y+2z=16$ and $x+2y-3z=7$, with $x$ intercept $-4$.',3)],[[M('The line direction is proportional to the plane normal $(3,-1,2)$.'),A('The factor is $-2$, hence $p=-4$.')],[M('Substitute $(1,4,2)+\\lambda(-6,2,-4)$ into the plane.'),A(f'$\\lambda={L(tau)}$.'),A(f'Intersection ${P(meet)}$.')],[A(f'$PA={V(p0-pt)}+\\lambda{V(d)}$.'),M('Set $PA\\cdot d=0$ for the perpendicular foot.'),A('$'+L(dot(p0-pt+S.Symbol('lambda')*d,d))+'=0$.'),A(f'$\\lambda={L(tfoot)}$.'),A(f'Foot ${P(foot)}$.'),M('Take the magnitude of the displacement from $P$ to the foot.'),A(f'Distance $={L(dist)}$.')],[M('The required normal is the cross product of the two given normals.'),A(f'$n_3={V(n3)}$.'),A('Through $(-4,0,0)$, the required plane is $'+eqplane(n3,axis)+'$.')]])
