p=S.Matrix([4,8,18]);fish=S.Matrix([10,-16,0]);duck=S.Matrix([8,-6,5]);vel=S.simplify(13*(fish-p)/norm(fish-p));tau=S.simplify(dot(duck-p,vel)/dot(vel,vel));dive=norm(fish-p)/13;assert 0<tau<dive
add(170,'Vector motion and closest approach',f'A seabird at ${P(p)}$ dives directly towards a fish at ${P(fish)}$ at a constant speed of $13$ m/s. A duck remains at ${P(duck)}$. All coordinates are in metres and the dive begins at $t=0$.',[('Find the bird’s velocity vector.',2),('Find the time during the dive when the bird is nearest the duck.',4)],[[M('Normalize the displacement to the fish and multiply by the speed $13$.'),A(f'$\\mathbf v={V(vel)}$ m/s.')],[M('At closest approach, the displacement from the duck to the bird is perpendicular to $v$.'),A('$[(p-\\text{duck})+tv]\\cdot v=0$.'),A(f'$t={L(tau)}\\approx{N(tau)}$ seconds.'),RR(f'This lies between $0$ and the arrival time ${N(dive)}$ seconds, so it is the closest point during the dive.')]])
