add(171,'Triangle angle constraints','In triangle $ABC$, let $B=\\angle ABC$ and $C=\\angle BCA$. It is given that $3\\sin B-4\\cos C=4$ and $4\\sin C-3\\cos B=2$.',[('Show that $\\sin(B+C)=5/24$.',6),('Prove that $A=\\angle BAC$ has only one possible value, and find it.',5)],[[M('Square both equations and add them.'),A('$9\\sin^2B+16\\cos^2C-24\\sin B\\cos C+16\\sin^2C+9\\cos^2B-24\\sin C\\cos B=20$.'),M('Use the two Pythagorean identities.'),A('$25-24(\\sin B\\cos C+\\cos B\\sin C)=20$.'),A('$25-24\\sin(B+C)=20$.'),A('$\\sin(B+C)=5/24$.')],[M('From $3\\sin B-4\\cos C=4$ and $3\\sin B\\le3$, infer $\\cos C\\le-1/4$.'),RR('Thus $C>90^\\circ$, so $B+C>90^\\circ$ and $0<A<90^\\circ$.'),A('$\\sin A=\\sin[\\pi-(B+C)]=5/24$.'),RR('Sine is one-to-one on the acute-angle interval, eliminating the supplementary branch.'),A(f'$A=\\arcsin(5/24)={N(math.degrees(math.asin(5/24)))}^\\circ$.')]],note='New consistent coefficients. The two original-style trigonometric constraints were solved numerically to confirm a positive triangle-angle pair, and the unique acute remaining angle follows analytically.')
leg=18;h=leg/math.sqrt(2);target=.9*.5*leg*leg;grazing=lambda b:math.pi*b*b/4-b*b*math.acos(h/b)+h*math.sqrt(b*b-h*h);broot=brentq(lambda b:grazing(b)-target,h+1e-7,leg)
add(172,'Grazing in a triangular field','A right isosceles field has perpendicular sides of length $18$ m. A cow is tethered at the right-angle vertex, with the rope confined to the field. Initially the rope is $12$ m long. It is later replaced by a rope of length $b$, where $12<b<18$.',[('Find the percentage of the field accessible with the $12$ m rope, to the nearest percent.',3),('Show that grazing exactly $90%$ of the field requires $b^2[\\pi/4-\\arccos(9\\sqrt2/b)]+9\\sqrt2\\sqrt{b^2-162}=145.8$.',7),('Find $b$ to two decimal places.',2)],[[M('The altitude to the hypotenuse is $9\\sqrt2>12$, so the grazing region is a quarter-circle.'),A('Its area is $\\pi(12)^2/4=36\\pi$, while the field area is $162$.'),A('Percentage $=100(36\\pi)/162\\approx70\\%$ to the nearest percent.')],[A('The distance from the tether to the hypotenuse is $h=9\\sqrt2$.'),RR('At $b=h$, the grazed area is $40.5\\pi<145.8$, so the required rope satisfies $b>h$ and crosses the hypotenuse.') ,M('Subtract the circular cap beyond the hypotenuse from the quarter-circle.'),A('The cap has half-angle $\\phi=\\arccos(h/b)$.'),A('Cap area $=b^2\\phi-h\\sqrt{b^2-h^2}$.'),A('Accessible area $=\\pi b^2/4-b^2\\arccos(h/b)+h\\sqrt{b^2-h^2}$.'),A('Set this equal to $0.9(162)=145.8$ and substitute $h=9\\sqrt2$ to obtain the stated equation.')],[M('Solve numerically on $9\\sqrt2<b<18$.'),A(f'$b={broot:.2f}$ m.')]],polygon_svg({'O':(70,260),'A':(70,35),'B':(405,260)},[('O','A'),('A','B'),('B','O')],extras='<text x="25" y="150" font-size="16">18 m</text><text x="220" y="290" font-size="16">18 m</text><path d="M70 240 L90 240 L90 260" fill="none" stroke="#475569" stroke-width="1"/>'))
add(173,'Reciprocal trigonometric equations','Consider $1/\\sin x+1/\\cos x=2\\sqrt6$, where $0<x<\\pi/2$.',[('Using the exact values of $\\sin15^\\circ$ and $\\cos15^\\circ$, verify that $x=\\pi/12$ is a solution.',3),('Find the other solution exactly.',5)],[[A('$\\sin15^\\circ=(\\sqrt6-\\sqrt2)/4$, $\\cos15^\\circ=(\\sqrt6+\\sqrt2)/4$.'),M('Their sum is $\\sqrt6/2$ and product is $1/4$.'),A('$1/\\sin15^\\circ+1/\\cos15^\\circ=(\\sqrt6/2)/(1/4)=2\\sqrt6$.')],[M('Let $u=\\sin x+\\cos x>0$. Then $\\sin x\\cos x=(u^2-1)/2$.'),A('The equation becomes $\\sqrt6u^2-u-\\sqrt6=0$.'),A('Its roots are $u=\\sqrt6/2$ and $u=-\\sqrt6/3$; reject the negative root.'),M('Thus $\\sin2x=u^2-1=1/2$.'),A('$2x=\\pi/6$ or $5\\pi/6$, so the other solution is $x=5\\pi/12$.')]])
