add(175,'Lines and planes through vectors',f'$OA={V(pa)}$, $OB={V(pb)}$, and $OC={V(pc)}$.',[('Find a vector equation of line $AB$.',3),('Classify the relationship of lines $AB$ and $OC$.',6),('Find the plane $\\Pi_1$ through $A$ perpendicular to $OC$.',3),('Show that all of $AB$ lies in $\\Pi_1$.',2),(f'Verify that ${V(n2)}$ is perpendicular to plane $OAC$.',3),('Find a normal to plane $OBC$.',1),('Find the acute angle between planes $OAC$ and $OBC$ to the nearest degree.',4)],[[M('Subtract the two point vectors.'),A(f'$AB={V(d)}$.'),A(f'$\\mathbf r={V(pa)}+t{V(d)}$.')],[A('The directions $AB$ and $OC$ are not proportional.'),M('Use the scalar triple product to test coplanarity.'),A(f'$AB\\times OC={V(cross(d,pc))}$.'),A(f'$OA\\cdot(AB\\times OC)={triple}\\ne0$.'),RR('Thus the lines are not coplanar and cannot intersect.'),A('They are skew.')],[A(f'The normal is $OC={V(pc)}$.'),M('Use its scalar product with $r-A$.'),A('$\\Pi_1:'+eqplane(pc,pa)+'$.')],[A('Point $A$ satisfies the plane equation.'),RR('$AB\\cdot OC=0$, so moving any distance in direction $AB$ keeps the plane equation unchanged.')],[M('Take the proposed normal’s scalar products with $OA$ and $OC$.'),A('Both scalar products are zero.'),RR('Since $OA,OC$ are independent directions in the plane, the non-zero vector is perpendicular to the plane.')],[A(f'A normal is $OB\\times OC={V(n3)}$.')],[M('Use the acute angle between the two normals.'),A('$\\cos\\theta='+L(co)+'$.'),A(f'$\\theta={angle:.8f}^\\circ$.'),A(f'To the nearest degree, $\\theta={round(angle)}^\\circ$.')]])
