add(176,'Intersecting-circle lens','Two circles have centres $A,B$, radii $4r$ and $2r$, and $AB=4r$. They meet at $C,D$. Let $\\alpha=\\angle CAD$ and $\\theta=\\angle CBD$ be the minor central angles, in radians. The shaded lens is the common interior.',[('Express the lens area using $r,\\alpha,\\theta$.',3),('Show that $\\alpha=4\\arcsin(1/4)$.',2),('Find $r$ when the lens area is $20$ cm$^2$.',6)],[[M('Add the two circular-segment areas.'),A('The first segment area is $8r^2(\\alpha-\\sin\\alpha)$.'),A('Lens area $=8r^2(\\alpha-\\sin\\alpha)+2r^2(\\theta-\\sin\\theta)$.')],[M('In isosceles triangle $ABC$, $AB=AC=4r$ and $BC=2r$, so $\\sin(\\angle BAC/2)=1/4$.'),A('Since $\\alpha=2\\angle BAC$, $\\alpha=4\\arcsin(1/4)$.')],[M('The base-angle relation in triangle $ABC$ gives $\\theta=\\pi-\\alpha/2$.'),A(f'$\\alpha={al:.8f}$, $\\theta={be:.8f}$ radians.'),M('Substitute the angles in the lens-area expression.'),A(f'$20=({factor:.8f})r^2$.'),A(f'$r^2={20/factor:.8f}$.'),A(f'$r={N(rad)}$ cm, taking the positive root.')]],diag,note='Both circle radii and shared-area target changed. Lens formula, central angles and positive radius checked numerically; SVG reconstructed from the two exact circle radii and centre distance.')
