add(177,'Parallelograms and planes','Distinct non-collinear points $A,B,C,D$ satisfy $\\overrightarrow{AD}=\\overrightarrow{BC}$. Their position vectors are $A=(4,-1,2)$, $B=(p,-4,5)$, $C=(1,q,3)$ and $D=(6,5,r)$.',[('Explain why $ABCD$ is a parallelogram and prove $AB=DC$ as vectors.',4),('Find $p,q,r$.',4),('Find the area of $ABCD$.',4),('Find a vector equation of the line through its diagonal intersection and normal to its plane.',4),('Find the plane equation.',3),('Find its intercepts $P,Q,R$ on the $x,y,z$ axes, and the length $PR$.',4)],[[RR('The opposite sides $AD$ and $BC$ are equal and parallel, which gives a parallelogram under the non-collinearity assumption.'),A('$d-a=c-b$.'),M('Rearrange the position-vector equation.'),A('$b-a=c-d$, so $AB=DC$.')],[M('Equate corresponding components of $(2,6,r-2)=(1-p,q+4,-2)$.'),A('$p=-1$.'),A('$q=2$.'),A('$r=0$.')],[A(f'$AB={V(ab)}$, $AD={V(ad)}$.'),M('Area is $|AB\\times AD|$.'),A(f'$AB\\times AD={V(n)}$.'),A(f'Area $={L(norm(n))}$.')],[M('The diagonals bisect each other.'),A(f'$M=(A+C)/2={P(mid)}$.'),A(f'A normal direction is ${V(ns)}$.'),A(f'$\\mathbf r={V(mid)}+t{V(ns)}$.')],[M('Use $n\\cdot(r-A)=0$.'),A(f'The constant is $n\\cdot A={K}$.'),A('$'+eqplane(ns,pa)+'$.')],[M('Set two coordinates to zero in turn.'),A(f'$P=({L(px)},0,0)$, $Q=(0,{L(qy)},0)$, $R=(0,0,{L(rz)})$.',2),A(f'$PR=\\sqrt{{({L(px)})^2+({L(rz)})^2}}={L(pr)}$.')]])
add(178,'Integer parameters in line-plane geometry','A line has Cartesian form $(x-a)/4=(y-2)/b=-(z-1)$, where $a,b$ are integers and $b\\ne0$. A plane has equation $2x+3y-z=9$.',[('Show that the line cannot be perpendicular to the plane.',3),('If the line lies in the plane, find $a,b$.',4),('In a different case, the acute line-plane angle is $\\arcsin(5\\sqrt6/14)$. Find $b$, and then find $a$ if the intersection has $z=-1$.',11)],[[A('Line direction $(4,b,-1)$ and plane normal $(2,3,-1)$.'),M('Perpendicularity would require these to be proportional.'),RR('The first-component ratio is $2$, but the third-component ratio is $1$, so this is impossible.')],[M('For containment, direction must be perpendicular to the plane normal.'),A('$8+3b+1=0$, so $b=-3$.'),M('The point $(a,2,1)$ must lie on the plane.'),A('$2a+6-1=9$, so $a=2$.')],[M('Apply the line-plane angle formula.'),A('$5\\sqrt6/14=|3b+9|/(\\sqrt{14}\\sqrt{b^2+17})$.'),M('Square and clear denominators.'),A('$25(6)(14)(b^2+17)=196(3b+9)^2$.'),A('Simplifying gives $2b^2-63b+118=0$.'),M('Factor: $(b-2)(2b-59)=0$.'),A('$b=2$ or $59/2$; integrality forces $b=2$.'),A('The line is $(a,2,1)+t(4,2,-1)$.'),M('$z=-1$ gives $t=2$.'),A('The intersection is $(a+8,6,-1)$, so $2(a+8)+18+1=9$.'),A('$a=-13$.')]])
