add(182,'Common perpendicular to skew lines',f'Lines are $L_1:\\mathbf r={V(p)}+s{V(d)}$ and $L_2:\\mathbf r={V(q)}+t{V(e)}$.',[('Show that the lines are skew.',4),('Find their acute angle to the nearest degree.',4),('Find a vector perpendicular to both lines and an equation of their common perpendicular which intersects each line.',10)],[[A('The directions are not proportional.'),M('Test whether the joining vector lies in their common direction plane.'),A(f'$(q-p)\\cdot(d\\times e)={dot(q-p,n)}\\ne0$.'),RR('They are non-coplanar, hence skew.')],[M('Use the absolute scalar-product formula.'),A('$\\cos\\theta='+L(cosang)+'$.'),A(f'$\\theta={ang:.8f}^\\circ$.'),A(f'To the nearest degree, $\\theta={round(ang)}^\\circ$.')],[M('Find $d\\times e$.'),A(f'$n={V(n)}$ is perpendicular to both.'),M('Let $P=p+sd$ and $Q=q+te$; impose $PQ\\cdot d=PQ\\cdot e=0$.'),A('$'+L(dot(rel,d))+'=0$.'),A('$'+L(dot(rel,e))+'=0$.'),M('Solve the simultaneous equations.'),A(f'$s={L(sol[ss])}$, $t={L(sol[tt])}$.'),A(f'$P={P(Pclose)}$ and $Q={P(Qclose)}$.'),A(f'The common perpendicular is $\\mathbf r={V(Pclose)}+u{V(n)}$, $u\\in\\mathbb R$.'),RR('Its direction is normal to both given directions; the computed points lie on the respective lines and their displacement is a multiple of $n$, so it intersects both.')]])
