def fix_percent(txt):
 def inside(m):return '$'+re.sub(r'(?<!\\)%',lambda _:r'\%',m.group(1))+'$'
 return re.sub(r'\$([^$]*?)\$',inside,txt)
for qq in Q.values():
 qq['stem']=fix_percent(qq['stem'])
 for pp in qq['parts']:pp['prompt']=fix_percent(pp['prompt'])
 for gg in qq['markScheme']:
  for ss in gg['steps']:ss['text']=fix_percent(ss['text'])
save()
